-- Report ID : RPT_077
-- Report    : Lead Time Extract
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,     im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,     im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,     im.STATUS                                             AS item_status,     ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'         WHEN 'E' THEN 'External Finisher'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS item_loc_status_desc,     ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'     END                                                   AS stock_category_desc,     ril.SOURCE_WH                                         AS source_warehouse,    ril.PRIMARY_REPL_SUPPLIER                             AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     isc.ORIGIN_COUNTRY_ID                                 AS origin_country,     isc.LEAD_TIME                                         AS supp_lead_time_global,     isc.PICKUP_LEAD_TIME                                  AS pickup_lead_time_global,     ril.WH_LEAD_TIME                                      AS wh_to_store_lead_time,     ril.SUPP_LEAD_TIME                                    AS ril_supp_lead_time,     ril.PICKUP_LEAD_TIME                                  AS ril_pickup_lead_time,     ril.ADJ_SUPP_LEAD_TIME                                AS adj_supp_lead_time,     ril.ADJ_PICKUP_LEAD_TIME                              AS adj_pickup_lead_time,     iscl.PICKUP_LEAD_TIME                                 AS loc_pickup_lt_override,     NVL(ril.SUPP_LEAD_TIME,      isc.LEAD_TIME)           AS effective_supp_lead_time,     NVL(iscl.PICKUP_LEAD_TIME,         NVL(ril.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME))  AS effective_pickup_lt,     NVL(iscl.PICKUP_LEAD_TIME,         NVL(ril.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME))         + NVL(ril.WH_LEAD_TIME, 0)                        AS total_pipeline_days,     CASE         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 1  AND 7              THEN '1 - 7 Days (Short)'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 8  AND 14              THEN '8 - 14 Days'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) BETWEEN 15 AND 30              THEN '15 - 30 Days (Medium)'         WHEN NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME) > 30              THEN '30+ Days (Long)'         ELSE 'NOT SET'     END                                                   AS lead_time_bucket,      CASE         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME != isc.PICKUP_LEAD_TIME         THEN 'LOC PICKUP LT OVERRIDE ACTIVE'         WHEN iscl.PICKUP_LEAD_TIME IS NOT NULL              AND iscl.PICKUP_LEAD_TIME = isc.PICKUP_LEAD_TIME         THEN 'OVERRIDE MATCHES GLOBAL'         ELSE 'USING GLOBAL DEFAULT'     END                                                   AS lt_override_status,     CASE         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(NVL(iscl.PICKUP_LEAD_TIME,                      NVL(ril.PICKUP_LEAD_TIME,                          isc.PICKUP_LEAD_TIME)), 0) = 0         THEN 'MISSING - REQUIRED'         WHEN ril.STOCK_CAT IN ('C','D','L','W')              AND NVL(NVL(iscl.PICKUP_LEAD_TIME,                      NVL(ril.PICKUP_LEAD_TIME,                          isc.PICKUP_LEAD_TIME)), 0) > 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                   AS pickup_lt_compliance,     CASE         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND NVL(ril.WH_LEAD_TIME, 0) = 0         THEN 'MISSING - REQUIRED'         WHEN il.LOC_TYPE = 'S'              AND ril.STOCK_CAT IN ('C','L','W')              AND NVL(ril.WH_LEAD_TIME, 0) > 0         THEN 'OK'         ELSE 'NOT REQUIRED'     END                                                   AS wh_lt_compliance,     isc.SUPP_PACK_SIZE                                    AS supplier_pack_size,     isc.INNER_PACK_SIZE                                   AS inner_pack_size,     isc.UNIT_COST                                         AS supplier_unit_cost,     ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost,     TRUNC(SYSDATE)         + NVL(NVL(iscl.PICKUP_LEAD_TIME,               NVL(ril.PICKUP_LEAD_TIME,                   isc.PICKUP_LEAD_TIME)), 0)         + NVL(ril.WH_LEAD_TIME, 0)                        AS estimated_arrival_date  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                   = il.ITEM                                                      AND  ril.LOCATION               = il.LOC     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                   = im.ITEM                                                      AND  im.TRAN_LEVEL              = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                    = c.DEPT                                                      AND  im.CLASS                   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                    = sc.DEPT                                                      AND  im.CLASS                   = sc.CLASS                                                      AND  im.SUBCLASS                = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                   = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND       = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND    = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM                   = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = iscl.SUPPLIER                                                      AND  iscl.LOC                   = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER  = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION               = st.STORE                                                      AND  il.LOC_TYPE                = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION               = wh.WH                                                      AND  il.LOC_TYPE                = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM                   = ils.ITEM                                                      AND  ril.LOCATION               = ils.LOC                                                      AND  ils.LOC_TYPE               = il.LOC_TYPE  WHERE     (         NVL(isc.LEAD_TIME,           0) > 0         OR NVL(isc.PICKUP_LEAD_TIME, 0) > 0         OR NVL(ril.WH_LEAD_TIME,     0) > 0         OR NVL(ril.SUPP_LEAD_TIME,   0) > 0     )     AND ril.REPL_METHOD  IS NOT NULL     AND il.STATUS        IN ('A', 'C')     AND im.STATUS         = 'A'  ORDER BY     NVL(isc.LEAD_TIME, 0) DESC,     d.DEPT_NAME,     c.CLASS_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END